import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

const Login = () => {
  const navigate = useNavigate();
  const { login, signup } = useAuth();
  const [mode, setMode] = useState("signin");
  const [form, setForm] = useState({
    schoolCode: "",
    name: "",
    email: "",
    password: "",
    confirmPassword: "",
  });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const onChange = (event) => {
    setForm((prev) => ({ ...prev, [event.target.name]: event.target.value }));
  };

  const onSubmit = async (event) => {
    event.preventDefault();
    setError("");

    try {
      setLoading(true);

      let user;
      if (mode === "signup") {
        if (!form.schoolCode || !form.name || !form.email || !form.password || !form.confirmPassword) {
          setError("School code, admin name, email and password are required");
          return;
        }
        if (form.password !== form.confirmPassword) {
          setError("Passwords do not match");
          return;
        }
        user = await signup({
          schoolCode: form.schoolCode,
          name: form.name,
          email: form.email,
          password: form.password,
        });
      } else {
        if (!form.email || !form.password) {
          setError("Email and password are required");
          return;
        }
        user = await login(form.email, form.password);
      }

      if (user.role === "admin") {
        navigate("/admin");
      } else {
        navigate("/teacher");
      }
    } catch (requestError) {
      setError(requestError.response?.data?.message || "Login failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-card">
        <div className="auth-mode-switch">
          <button
            type="button"
            className={`auth-mode-btn ${mode === "signin" ? "active" : ""}`}
            onClick={() => {
              setMode("signin");
              setError("");
            }}
          >
            Sign In
          </button>
          <button
            type="button"
            className={`auth-mode-btn ${mode === "signup" ? "active" : ""}`}
            onClick={() => {
              setMode("signup");
              setError("");
            }}
          >
            Sign Up
          </button>
        </div>

        <h2>{mode === "signup" ? "Create Admin Account" : "Welcome Back"}</h2>
        <p>
          {mode === "signup"
            ? "Sign up first using school code and admin details"
            : "Sign in to continue to School Attendance"}
        </p>
        <form onSubmit={onSubmit}>
          {mode === "signup" && (
            <>
              <label>School Code</label>
              <input
                type="text"
                name="schoolCode"
                value={form.schoolCode}
                onChange={onChange}
                placeholder="Enter school code"
              />
              <label>Admin Name</label>
              <input
                type="text"
                name="name"
                value={form.name}
                onChange={onChange}
                placeholder="Enter admin name"
              />
            </>
          )}

          <label>Email</label>
          <input type="email" name="email" value={form.email} onChange={onChange} placeholder="admin@school.com" />
          <label>Password</label>
          <input type="password" name="password" value={form.password} onChange={onChange} placeholder="Enter password" />
          {mode === "signup" && (
            <>
              <label>Confirm Password</label>
              <input
                type="password"
                name="confirmPassword"
                value={form.confirmPassword}
                onChange={onChange}
                placeholder="Re-enter password"
              />
            </>
          )}
          {error && <div className="error-text">{error}</div>}
          <button type="submit" disabled={loading}>
            {loading
              ? mode === "signup"
                ? "Creating account..."
                : "Signing in..."
              : mode === "signup"
                ? "Create Account"
                : "Login"}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;
